INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (125, 2, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":125,"image_path":null,"slug":"vu-2025-rw-q53","statement":"Para além das guerras Rússia-Ucrânia e Israel-Palestina, estão em curso, em quase todos os continentes, conflitos que retratam mutações geopolíticas aceleradas. Há um movimento de redefinição de fronteiras até então reconhecidas pela comunidade internacional e, de certo modo, protegidas por um complexo arcabouço normativo. Na América Latina, por exemplo, a Venezuela reivindica da Guiana a região de Essequibo, cujo limite fronteiriço foi definido há 125 anos.\n\n(Adaptado de https://www.courrierinternational.com/article/analyse-depuis-les-guerres-en-ukraine-et-a-gaza-les-frontieres-ne-sont-plus-intangibles. Acesso em 06/06/2024.)\n\nTendo em vista seus conhecimentos e considerando o texto anterior, é correto dizer que a fronteira entre países é essencialmente","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
