INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (144, 21, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":144,"image_path":null,"slug":"vu-2025-rw-q72","statement":"Leia o resumo de uma pesquisa que, em 2021, já alertava para\nquestões climáticas e fatores a elas relacionados.\nPolitics of attributing extreme events\nto climate change\nClimate change shapes weather events. However, describing it\nas the cause of disasters can be misleading, since disasters are\ncaused by pre-existing fragilities and inequalities on the ground.\nAttribution is not neutral. Hence, analytic frames that attribute\ndisaster to climate can divert attention from place-based vulnerabilities and their sociopolitical causes. While politicians may\nblame climate change, the public may hold the government\naccountable for inadequate investments in flood or drought\nprevention. To be strategic and moral, framing choices must\ntherefore be sensitive to context and to how the values implicit\nwithin analytic frames about the causes of disasters shape\npolicy responses. Such sensitivity requires multicausal analysis\nof weather-linked disasters to reduce the damages. Through\nexamples from around the world, especially Brazil, we discuss\nhow and why climate-centric disaster framing can erase from\nview—and, thus, from policy agendas—the very socioeconomic\nand political factors that centrally cause vulnerability and suffering\nin weather extremes.\n(Adaptado de https://wires.onlinelibrary.wiley.com/doi/full/10.1002/wcc.750. Acesso em\n15/05/2024.)\nQual alternativa expressa corretamente os argumentos dos autores do texto?","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (144, 'vu-2025-rw-q72', 21) ;
