INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (76, 25, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":76,"image_path":null,"slug":"vu-2025-rw-q04","statement":"Nos estudos sobre a Antiguidade Clássica produzidos até o final\ndo século XX, era costumeira a afirmação de que as mulheres\nem Atenas não participavam da política. A definição de “política” na Grécia, todavia, era feita a partir dos olhos do mundo\nmoderno, e, nesse caso, era um sinônimo de “cidadania”. O\ncidadão ateniense era homem, filho de pai e mãe atenienses.\nAs mulheres, estrangeiros e escravos não gozavam do mesmo\nstatus. Após os anos de 2000, a partir de críticas de estudiosos,\na definição de “política” e de “cidadania” na Grécia Clássica\npassou a ser repensada e a capacidade de ação das mulheres\natenienses no espaço público foi redimensionada. Nesses estudos, as mulheres cidadãs de Atenas ganham visibilidade. Filhas\nde pai e mãe atenienses, nascidas em Atenas, tinham limitações\nde voto, mas desempenhavam funções no mundo cívico. Elas\nnão podiam, por causa de seu sexo, ser juradas ou magistradas,\npor exemplo, mas estavam vivendo no mesmo universo público,\nsendo também cidadãs.\n(Adaptado de CUCHET, V . S. Quais direitos políticos para as cidadãs da Atenas clássica?.\nHélade, 4(1), p. 143-158, 2018.)\nTendo em vista seus conhecimentos sobre Grécia Antiga e considerando o excerto anterior, assinale a alternativa correta.","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (76, 'vu-2025-rw-q04', 25) ;
INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (207, 25, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":207,"image_path":null,"slug":"vu-2025-sx-q63","statement":"Nos estudos sobre a Antiguidade Clássica produzidos até o final\ndo século XX, era costumeira a afirmação de que as mulheres\nem Atenas não participavam da política. A definição de “política” na Grécia, todavia, era feita a partir dos olhos do mundo\nmoderno, e, nesse caso, era um sinônimo de “cidadania”. O\ncidadão ateniense era homem, filho de pai e mãe atenienses.\nAs mulheres, estrangeiros e escravos não gozavam do mesmo\nstatus. Após os anos de 2000, a partir de críticas de estudiosos,\na definição de “política” e de “cidadania” na Grécia Clássica\npassou a ser repensada e a capacidade de ação das mulheres\natenienses no espaço público foi redimensionada. Nesses estudos, as mulheres cidadãs de Atenas ganham visibilidade. Filhas\nde pai e mãe atenienses, nascidas em Atenas, tinham limitações\nde voto, mas desempenhavam funções no mundo cívico. Elas\nnão podiam, por causa de seu sexo, ser juradas ou magistradas,\npor exemplo, mas estavam vivendo no mesmo universo público,\nsendo também cidadãs.\n(Adaptado de CUCHET, V . S. Quais direitos políticos para as cidadãs da Atenas clássica?.\nHélade, 4(1), p. 143-158, 2018.)\nTendo em vista seus conhecimentos sobre Grécia Antiga e considerando o excerto anterior, assinale a alternativa correta.","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
