INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (78, 27, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":78,"image_path":null,"slug":"vu-2025-rw-q06","statement":"“A terra [Rio de Janeiro] continua ainda a parecer-me muito mal.\nÉ rodeada de serras inacessíveis, a maior parte delas são uma\nrocha viva, e de todas fazem uma vista sumamente desagradável. Acho estes povos sumamente pobres e, como não têm\ngêneros seus que lhes constituam ao menos um ramo certo de\ncomércio, pouca esperança tenho de os pôr melhor nesta parte.\nEm uma palavra, meu colega, isto está um cadáver que vai para\na sepultura [...]; parece-me ser este o mais próprio retrato em\nque presentemente se acha o Governo do Rio de Janeiro.”\n(Marquês de Lavradio (Governador do Rio de Janeiro, 1769-1779). Carta de Amizade\nEscrita a Manuel da Cunha de Menezes em Pernambuco, em 13 de dezembro de 1769.\nIn: Marquês de Lavradio. Cartas do Rio de Janeiro, 1769-1776. Rio de Janeiro: Secretaria\nde Estado de Educação e Cultura, p. 10, 1978.)\nTendo em vista seus conhecimentos sobre o século XVIII e considerando as informações do excerto, assinale a alternativa correta.","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (78, 'vu-2025-rw-q06', 27) ;
