INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (82, 31, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":82,"image_path":null,"slug":"vu-2025-rw-q10","statement":"Em 2004, Néstor Kirchner – presidente argentino à época – cedeu à sociedade civil a Escola de Mecânica da Marinha (ESMA),\num antigo centro clandestino de detenção e tortura durante\na ditadura (1976 e 1983). O motivo era a construção de uma\nespécie de museu nacional da memória das atrocidades cometidas pelo regime. Entre as imagens das mães e avós da Plaza de\nMayo, entre organizações de luta que celebravam o reconhecimento de um trabalho sustentado por décadas, emergia ao\nlado do palco uma imagem disruptiva: um poncho vermelho.\nDestacava-se um rosto indígena. Era um dos líderes do Movimento Indígena Argentino; o líder pedia a inclusão dos povos originários no futuro museu: “A questão não é – como os\nantropólogos fazem – simplesmente sermos incluídos em um\nmuseu, como se estivéssemos apenas sendo adicionados. Queremos fazer parte da história nacional.\"\n(Adaptado de RUFER, M. Nación y condición pos-colonial. In: BIDASECA, K. (Org.) Genealogías críticas de la colonialidad en América Latina, África, Oriente . Buenos Aires:\nCLACSO, 2016.)\nTendo em vista seus conhecimentos sobre memória política na\nArgentina e considerando as informações do texto, é correto\nafirmar que","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (82, 'vu-2025-rw-q10', 31) ;
