INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (83, 32, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":83,"image_path":null,"slug":"vu-2025-rw-q11","statement":"Texto 1\nNo final do século XIX, a escritora Charlotte Perkins Gilman observava a necessidade de reformas urbanas e habitacionais que\ncombinassem a privacidade da família com a vida em coletivo.\nEla defendia que grandes cidades fossem equipadas com conjuntos amplos de apartamentos que contariam com cozinhas\ncomuns e com pessoas contratadas coletivamente pelas famílias\npara serviços domésticos. A atenção às crianças seria garantida\npor cuidadores profissionais e professores dentro das creches.\n(Adaptado de GILMAN, C.P . Mulheres e economia. In: DAFLON, V .; SORJ, B. Clássicas do\npensamento social. Rio de Janeiro: Rosa dos Tempos, p.129-130, 2021.)\nTexto 2\nQuase um século depois, em 1996, o então presidente dos EUA\nBill Clinton implementou reformas nas políticas de proteção social daquele país. Entre as mudanças, o Estado deixou de prover\nauxílio financeiro a mães pobres que criam os filhos sozinhas e\nessa responsabilidade passou para o pai biológico da criança.\nEssa reforma acentuou um vínculo social entre mulheres e homens, vínculo este que elas não necessariamente gostariam de\nmanter. A reforma as tornou sobretudo dependentes economicamente deles.\n(Adaptado de COOPER, M. Family values: between neoliberalism and the new social\nconservatism. New York: Zone Books, p. 67-68, 2017.)\nConsiderando os textos 1 e 2, é correto afirmar que os efeitos,\npara as relações sociais, das reformas neles descritas","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (83, 'vu-2025-rw-q11', 32) ;
INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (214, 32, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":214,"image_path":null,"slug":"vu-2025-sx-q70","statement":"Texto 1\nNo final do século XIX, a escritora Charlotte Perkins Gilman observava a necessidade de reformas urbanas e habitacionais que\ncombinassem a privacidade da família com a vida em coletivo.\nEla defendia que grandes cidades fossem equipadas com conjuntos amplos de apartamentos que contariam com cozinhas\ncomuns e com pessoas contratadas coletivamente pelas famílias\npara serviços domésticos. A atenção às crianças seria garantida\npor cuidadores profissionais e professores dentro das creches.\n(Adaptado de GILMAN, C.P . Mulheres e economia. In: DAFLON, V .; SORJ, B. Clássicas do\npensamento social. Rio de Janeiro: Rosa dos Tempos, p.129-130, 2021.)\nTexto 2\nQuase um século depois, em 1996, o então presidente dos EUA\nBill Clinton implementou reformas nas políticas de proteção social daquele país. Entre as mudanças, o Estado deixou de prover\nauxílio financeiro a mães pobres que criam os filhos sozinhas e\nessa responsabilidade passou para o pai biológico da criança.\nEssa reforma acentuou um vínculo social entre mulheres e homens, vínculo este que elas não necessariamente gostariam de\nmanter. A reforma as tornou sobretudo dependentes economicamente deles.\n(Adaptado de COOPER, M. Family values: between neoliberalism and the new social\nconservatism. New York: Zone Books, p. 67-68, 2017.)\nConsiderando os textos 1 e 2, é correto afirmar que os efeitos,\npara as relações sociais, das reformas neles descritas","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (214, 'vu-2025-sx-q70', 32) ;
INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (265, 32, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":265,"image_path":null,"slug":"vu-2025-ty-q49","statement":"Texto 1\nNo final do século XIX, a escritora Charlotte Perkins Gilman observava a necessidade de reformas urbanas e habitacionais que\ncombinassem a privacidade da família com a vida em coletivo.\nEla defendia que grandes cidades fossem equipadas com conjuntos amplos de apartamentos que contariam com cozinhas\ncomuns e com pessoas contratadas coletivamente pelas famílias\npara serviços domésticos. A atenção às crianças seria garantida\npor cuidadores profissionais e professores dentro das creches.\n(Adaptado de GILMAN, C.P . Mulheres e economia. In: DAFLON, V .; SORJ, B. Clássicas do\npensamento social. Rio de Janeiro: Rosa dos Tempos, p.129-130, 2021.)\nTexto 2\nQuase um século depois, em 1996, o então presidente dos EUA\nBill Clinton implementou reformas nas políticas de proteção social daquele país. Entre as mudanças, o Estado deixou de prover\nauxílio financeiro a mães pobres que criam os filhos sozinhas e\nessa responsabilidade passou para o pai biológico da criança.\nEssa reforma acentuou um vínculo social entre mulheres e homens, vínculo este que elas não necessariamente gostariam de\nmanter. A reforma as tornou sobretudo dependentes economicamente deles.\n(Adaptado de COOPER, M. Family values: between neoliberalism and the new social\nconservatism. New York: Zone Books, p. 67-68, 2017.)\nConsiderando os textos 1 e 2, é correto afirmar que os efeitos,\npara as relações sociais, das reformas neles descritas","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
