INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (85, 34, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":85,"image_path":null,"slug":"vu-2025-rw-q13","statement":"Texto 1\nEm Raízes do Brasil (São Paulo, Companhia das Letras, 2016),\nSérgio Buarque de Holanda argumenta que as formas de convívio social no país seriam ditadas preferencialmente por uma ética de fundo emotivo: a cordialidade. No entanto, a cordialidade\nnão seria sinônimo de afetividade ou de gentileza. Ela corresponderia a um mecanismo de defesa do indivíduo diante da sociedade e reforçaria sentimentos particularistas e antipolíticos,\ncaracterísticos do ambiente doméstico. Ao tipo social guiado\npela ética da cordialidade, o autor dá o nome de homem cordial.\nTexto 2\n\"Sabe, no fundo eu sou um sentimental\nTodos nós herdamos no sangue lusitano uma boa dosagem de\nlirismo (além da sífilis, é claro)\nMesmo quando as minhas mãos estão ocupadas em torturar,\nesganar, trucidar\nMeu coração fecha os olhos e sinceramente chora...\n(...)\nSe trago as mãos distantes do meu peito\nÉ que há distância entre intenção e gesto”\n(Trecho da canção “Fado Tropical”, de Chico Buarque de Holanda, 1973).\nTendo em vista os textos 1 e 2, é possível afirmar que o homem\ncordial","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (85, 'vu-2025-rw-q13', 34) ;
