INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (92, 41, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":92,"image_path":null,"slug":"vu-2025-rw-q20","statement":"O excerto a seguir, do livro Alice no país das maravilhas, de\nLewis Carrol, narra o encontro entre a protagonista e o Gato\nde Cheshire:\nO Gato apenas sorriu ao avistá-la. Alice achou que ele parecia\nafável. Mas como tinha garras muito compridas e dentes bem\ngraúdos, sentiu que devia tratá-lo com respeito.\n– Gatinho de Cheshire – começou a dizer timidamente, sem\nter certeza se ele gostaria de ser tratado assim, mas ele apenas\nabriu um pouco mais o sorriso. “Ótimo, parece que ele gostou”, pensou ela, e prosseguiu: – Podia me dizer, por favor, qual\né o caminho para sair daqui?\n– Isso depende muito do lugar para onde você quer ir – disse\no Gato.\n– Não me importa onde... – disse Alice.\n– Nesse caso não importa por onde você vá – disse o Gato.\n– ...conquanto que eu chegue a algum lugar – acrescentou Alice como explicação.\n– É claro que isso acontecerá – disse o Gato –, desde que você\nande por algum tempo.\n(CARROLL, L. Aventuras de Alice no país das maravilhas . Tradução de Sebastião Uchoa\nLeite. São Paulo: Editora 34, p. 68-69, 2016.)\n\nA partir da leitura do trecho e da compreensão do todo da narrativa, pode-se afirmar que o excerto é um exemplo","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (92, 'vu-2025-rw-q20', 41) ;
