INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (93, 42, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":93,"image_path":null,"slug":"vu-2025-rw-q21","statement":"A citação a seguir, de Vida e morte de M. J. Gonzaga de Sá, de\nLima Barreto, apresenta como o narrador conheceu o protagonista.\nNum país em que, com tanta facilidade, se fabricam manipansos milagrosos, ídolos aterradores e deuses onipotentes, causa\npasmo que a Secretaria dos Cultos não seja tão conhecida como\na da Viação. Há, entretanto, nela, no seu Museu e nos seus registros, muita cousa interessante e digna de exame.\nFoi, por ocasião de desempenhar-me da incumbência do meu\ndiretor, que vim a conhecer Gonzaga de Sá, afogado num mar\nde papeis, na seção de “alfaias, paramentos e imagens”, informando muito seriamente a consulta do vigário de Sumaré,\nversando sobre o número de setas que devia ter a imagem de\nS. Sebastião.\n(BARRETO, Lima. Vida e morte de M. J. Gonzaga de Sá. São Paulo: Edição da Revista do\nBrasil, p. 17, 1919.)\nA partir dessa citação e da leitura do romance, é correto afirmar\nque Lima Barreto usa a personagem Gonzaga de Sá para","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (93, 'vu-2025-rw-q21', 42) ;
