INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (111, 60, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":111,"image_path":null,"slug":"vu-2025-rw-q39","statement":"O percentual da energia metabólica de um macronutriente em um alimento pode ser obtido levando em conta tanto o percentual em massa desse macronutriente quanto a sua respectiva energia metabólica por massa. Dos macronutrientes que nos interessam, os principais são proteínas, carboidratos e gorduras; as fibras só entram nesses cálculos quando são digeríveis. As gorduras apresentam um valor de energia metabólica por massa cerca de 2,25 vezes o valor da energia metabólica associada a carboidratos ou a proteínas. Considere uma barra de chocolate cujos percentuais de energia são: proteínas, 5%; gorduras, 52%; carboidratos, 43%. A partir dessas informações, pode-se afirmar que, em comparação com os respectivos percentuais em energia, os percentuais em massa de:","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
