INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (112, 61, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":112,"image_path":null,"slug":"vu-2025-rw-q40","statement":"Para a safra de 2023/2024, prevê-se uma produção de 34 bilhões de litros de etanol, com geração de 408 bilhões de litros de vinhaça, subproduto de alto teor de matéria orgânica. Nas últimas décadas, visando à sustentabilidade, o emprego da vinhaça in natura evoluiu: seu descarte direto em rios e em áreas de sacrifício deu lugar à fertirrigação direta (devido ao alto teor de potássio do subproduto). A partir de 2015, empregando biodigestores anaeróbicos, a vinhaça in natura passou a ser convertida em biogás, o qual, após purificação, é denominado gás natural renovável. Em média, 1 m³ de vinhaça produz até 14 m³ de biogás, e o subproduto desse processo é a vinhaça líquida biodigerida, que continua sendo utilizada na fertirrigação. Em vista dessas informações, pode-se concluir que a sustentabilidade do processo de biodigestão da vinhaça in natura é devida à geração de energia renovável a partir da queima do:","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (112, 'vu-2025-rw-q40', 61) ;
