INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (113, 62, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":113,"image_path":null,"slug":"vu-2025-rw-q41","statement":"Os submarinos nucleares conseguem submergir por longos períodos, pois geram uma quantidade enorme de energia elétrica para ser usada internamente. Um dos desafios a serem enfrentados diz respeito à manutenção da atmosfera interna da embarcação, o que garantiria condições respiráveis. Para tanto, controlam-se as concentrações de oxigênio e gás carbônico. Em vista dessa descrição, você, como responsável por essa manutenção, sugeriria a combinação das seguintes ações:","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
