INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (122, 71, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":122,"image_path":null,"slug":"vu-2025-rw-q50","statement":"Estima-se que mais de dois milhões de espécies habitem os oceanos; entretanto, somente 10% da vida oceânica é conhecida.\n\nEm janeiro de 2024, uma expedição na costa do Chile avaliou um trecho de 2.900 km² de montanhas subaquáticas criadas por atividade vulcânica, o que resultou em uma região única com correntes marítimas e baixo teor de oxigênio, gerando um nível elevado de endemismo.\n\nEm menos de um mês, a expedição documentou cem novas espécies animais de profundidade, incluindo corais, esponjas, lagostas, polvos, caravelas, águas-vivas, peixes, camarões, entre outros.\n\n(Adaptado de https://www.nytimes.com/2024/03/10/science/new-species-sea-discovery.html. Acesso em 02/04/2024.)\n\nSobre essa expedição marinha, é correto afirmar que os animais","status":"draft","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
