INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (367, 316, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":367,"image_path":null,"slug":"vu-2026-ry-q07","statement":"Os dados da alfândega de Buenos Aires fixam em 18.100 o número de africanos oficialmente importados no porto entre 1597 e 1645. Durante alguns anos, a zona platense esteve aberta ao contrato de fornecimento de pessoas escravizadas (Asiento), com os navios negreiros saindo diretamente de Luanda para Buenos Aires. Nos anos de proibição, o contrabando ocorria por meio do Rio de Janeiro. Barcos ligavam os dois portos. No retorno, traziam prata lavrada e por lavrar e ouro, não só para o Rio de Janeiro, mas também para a Bahia e o Recife. Em torno das trocas de africanos pela prata do Peru (Potosí), esses interesses foram consolidados no Rio de Janeiro. Desse episódio resultou uma tradição religiosa conhecida: o culto a Nossa Senhora de Copacabana no Rio de Janeiro, oriundo do Baixo Peru em 1637. Nos anos seguintes, uma capela dedicada à santa foi erigida na praia que recebeu o seu nome.\n(Adaptado de ALENCASTRO, L. F. O Trato dos Viventes. São Paulo: Companhia das Letras, 2000, p. 110.)\n\nCom base no excerto, assinale a alternativa correta.","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (367, 'vu-2026-ry-q07', 316) ;
