INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (371, 320, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":371,"image_path":null,"slug":"vu-2026-ry-q11","statement":"“A OMC não será uma organização mundial de comércio até que a China seja um país-membro”, afirmou Mike Moore, diretor-geral da OMC. A assinatura de um acordo bilateral de comércio entre os Estados Unidos e a China teve uma repercussão positiva no mercado internacional, apesar da desconfiança de que a China poderá ter dificuldades para cumprir o prometido.\n\n“A China deu um passo grande em direção à OMC”, disse o presidente dos Estados Unidos, Bill Clinton. A União Europeia aprovou a assinatura do acordo. A adesão da China à OMC permitirá incluir no sistema comercial internacional a décima potência do planeta, que cresceu em média 9,6% ao ano desde 1980. O acordo será um teste importante para verificar se a economia chinesa aguentaria o impacto de sua incorporação à OMC e se continuaria com seu crescimento. Desde 1986, o país asiático busca ser aceito em um organismo de comércio internacional. Segundo nota chinesa, “ambas as partes estreitarão sua cooperação no seio da OMC para garantir no futuro o aumento de suas relações bilaterais e a prosperidade da economia mundial”.\n\n(De agências internacionais, “Sem a China, OMC não é mundial”, Folha de S. Paulo, ano 79, n. 25.794, 16 de novembro de 1999. Disponível em https://www1.folha.uol.com.br/fsp/dinheiro/fi1611199903.htm. Acesso em 05/08/2025.)\n\nComparando as expectativas sobre o ingresso da China na Organização Mundial de Comércio (OMC) expressas no texto com o contexto atual, é correto afirmar que","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (371, 'vu-2026-ry-q11', 320) ;
