INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (407, 337, '{"difficulty":"medium","editorial_version":"1.0.1","expected_seconds":null,"explanation":null,"id":407,"image_path":null,"slug":"vu-2026-ry-q47","statement":"Em uma creche se realiza o “dia da troca do brinquedo”. Cada criança leva um brinquedo para a escola e o guarda na Caixa Divertida. Ao final do dia, cada criança retira um brinquedo da Caixa Divertida sem olhar e o leva para brincar em casa.\n\nEm uma sala com cinco crianças, qual é a probabilidade de exatamente duas crianças retirarem da Caixa Divertida seus próprios brinquedos?","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
