INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (374, 342, '{"difficulty":"medium","editorial_version":"1.0.1","expected_seconds":null,"explanation":null,"id":374,"image_path":null,"slug":"vu-2026-ry-q14","statement":"É advogado com d mudo, estúpida!\nMirian Goldenberg\n\nAntropóloga e professora da Universidade Federal do Rio de Janeiro, é autora de “A Invenção de uma Bela Velhice”.\n\nFiz um vídeo para o Instagram sobre a minha coluna intitulada No dia 1º de abril, quase caí no golpe do “falso advogado”. No vídeo, confessei que quase morri de vergonha por quase ter caído em um golpe no Dia da Mentira.\n\nFiquei triste quando li alguns dos comentários sobre o vídeo: “AdEvogado?”; “Não é adevogado que fala”; “A desinformada que fala adêvogado aprendeu o que é golpe de verdade kkkk”; “Adevogado? Pode isso? Uma ‘intelequitual’ brasileira da linha de frente falando assim?”; “Um currículo e tanto e falando adevogado?”; “Chamou de adEvogado. Então não foi difícil entender por que caiu em golpe... Eu teria é vergonha de falar adEvogado”; “A palavra ‘advogado’ se pronuncia ‘advogado’, com o ‘d’ mudo. A pronúncia adevogado é um erro de ortoépia”; “É advogado com ‘d’ mudo, estúpida!”.\n\nPerguntei ao meu marido, que editou o vídeo, por que ele não me falou nada. Ele respondeu: “Porque eu acho bonitinho. Você é filha de advogado e tem dois irmãos advogados. Desde menina aprendeu a falar assim. Não é fácil falar ‘advogado’ com o ‘d’ mudo. Eu falo advogado com ‘i’: adivogado. Será que alguém consegue falar advogado com o ‘d’ mudo?”\n\nDa próxima vez que fizer uma denúncia importante, vou tentar falar advogado com o “d” mudo. Será que vou conseguir?\n\nAdaptado de GOLDENBERG, M. É advogado com d mudo, estúpida! Folha de São Paulo, 16/04/2025, B6. Acesso em 29/07/2025.\n\nConsiderando que consoantes mudas não são seguidas de uma vogal, e levando em conta as duas pronúncias para advogado mencionadas no texto, as críticas reproduzidas no segundo parágrafo revelam:","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (374, 'vu-2026-ry-q14', 342) ;
