INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (380, 348, '{"difficulty":"medium","editorial_version":"1.0.1","expected_seconds":null,"explanation":null,"id":380,"image_path":null,"slug":"vu-2026-ry-q20","statement":"Em seu ensaio “A vida não é útil”, Ailton Krenak elege Carlos\nDrummond de Andrade como um de seus “escudos”. Ele cita\na última estrofe de “O Homem; as Viagens”, poema publicado\nem As impurezas do Branco (1973). Reproduzimos, a seguir, a\nprimeira e a segunda estrofe desse poema:\n“O Homem; as Viagens\nO homem, bicho da Terra tão pequeno\nchateia-se na Terra\nlugar de muita miséria e pouca diversão,\nfaz um foguete, uma cápsula, um módulo\ntoca para a Lua\ndesce cauteloso na Lua\npisa na Lua\nplanta bandeirola na Lua\nexperimenta a Lua\ncoloniza a Lua\nciviliza a Lua\nhumaniza a Lua.\nLua humanizada: tão igual à Terra.\nO homem chateia-se na Lua.\nVamos para Marte – ordena a suas máquinas.\nElas obedecem, o homem desce em Marte\npisa em Marte\nexperimenta\ncoloniza\nciviliza\nhumaniza Marte com engenho e arte.\nMarte humanizado, que lugar quadrado.\n(...)”.\n(ANDRADE, C. D. O Homem; As viagens, As impurezas do Branco. In: Poesia Completa.\nRio de Janeiro, Editora Nova Aguilar, p. 718, 2002.)\n(KRENAK, A. A vida não é útil. Pesquisa e organização de Rita Carelli. São Paulo: Companhia das Letras, 2020.)\nEm relação às reflexões de Ailton Krenak, é correto afirmar que\nesse trecho do poema","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (380, 'vu-2026-ry-q20', 348) ;
