INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (381, 349, '{"difficulty":"medium","editorial_version":"1.0.1","expected_seconds":null,"explanation":null,"id":381,"image_path":null,"slug":"vu-2026-ry-q21","statement":"Leia os textos 1 e 2.\nTexto 1\nAos óculos\nSó fingem que põem\no mundo ao alcance\ndos meus olhos míopes.\nNa verdade, me exilam\ndele com filtrar-lhe\na menor imagem.\nJá não vejo as coisas\ncomo são: vejo-as como eles querem\nque as veja.\nLogo, são eles que veem,\nnão eu que, mesmo cônscio\ndo logro, lhes sou grato\npor anteciparem em mim\no Édipo curioso\nde suas próprias trevas.\n(PAES, J. P. Prosas seguidas de Odes mínimas. São Paulo: Companhia das Letras, p. 63,\n1992.)\nTexto 2\n“Do grego odé e do latim ōde (ou ōda), a ode era, na antiguidade clássica, um poema destinado a ser cantado, ou um canto\nalegre, triste ou lírico. Era um poema de alguma extensão, de\nelevado assunto ou nobre, expressando sentimentos ilustres,\nem homenagem a algo ou a alguém. Apresentava também a\nelaboração estrófica, bem como estilo formal nobre e cerimonioso”.\n(Adaptado do verbete “Ode”, elaborado por Ana Ladeira. In: CEIA, C. E-Dicionário de\ntermos literários (projeto abrigado pela Universidade Nova de Lisboa). Disponível em\nhttps://edtl.fcsh.unl.pt/encyclopedia/ode. Acesso em 31/05/2025.)\nÉ correto afirmar que a ode mínima de José Paulo Paes reelabora a definição clássica de “ode” ao","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (381, 'vu-2026-ry-q21', 349) ;
