INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (384, 352, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":384,"image_path":null,"slug":"vu-2026-ry-q24","statement":"O sineiro era um preto velho e doido. Não fazia mais que tocar o sino da capela, para a missa, aos domingos. O resto do tempo vivia calado ou resmungando. Ninguém lhe falava, embora fosse manso. [...] Com a razão, perdera a convivência dos mais. Vivia entregue aos pensamentos solitários, mergulhado na inconsciência e na solidão. A moça representava aos olhos dele alguma coisa mais do que uma simples criatura, era a sociedade humana, e uma sombra de sombra da consciência antiga.\n\n(ASSIS, M. de. Casa Velha. Apresentação e notas de Paulo Franchetti. Campinas, SP: Editora da UNICAMP, p. 85-86, 2023.)\n\nNo enredo de Casa Velha, é possível afirmar que a cena em que aparece a figura do sineiro cumpre o papel de","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
