INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (385, 353, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":385,"image_path":null,"slug":"vu-2026-ry-q25","statement":"Leia os versos da canção abaixo e assinale a alternativa correta.\n\nALVORADA\n\nAlvorada lá no morro, que beleza,\nNinguém chora, não há tristeza,\nNinguém sente dissabor.\nO sol colorindo é tão lindo, é tão lindo.\nE a natureza sorrindo, tingindo, tingindo.\nVocê também me lembra a alvorada\nQuando chega iluminando\nMeus caminhos tão sem vida.\nE o que me resta\né bem pouco, quase nada,\ndo que ir assim vagando\nnuma estrada perdida.\n\n(CARTOLA. Alvorada. In: Cartola. Rio de Janeiro: Marcus Pereira Discos, 1974.)","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (385, 'vu-2026-ry-q25', 353) ;
