INSERT INTO canonical_question_archive(question_id, canonical_question_id, original_row_json, archived_reason) VALUES (391, 359, '{"difficulty":"medium","editorial_version":"1.0.0","expected_seconds":null,"explanation":null,"id":391,"image_path":null,"slug":"vu-2026-ry-q31","statement":"A Agência Nacional do Petróleo (ANP) é responsável por implementar a política nacional de combustíveis e proteger os interesses dos consumidores quanto a preço, qualidade e oferta de produtos, além de especificar a qualidade dos derivados de petróleo, do gás natural e dos biocombustíveis. A Resolução ANP nº 907, de 2022, especifica características do Etanol Anidro Combustível (EAC), do Etanol Hidratado Combustível (EHC) e do Etanol Hidratado Combustível Premium (EHCP). Algumas delas estão na tabela:\n\nCombustível | Massa específica (kg/m³) | Teor alcoólico (% em massa)\nEAC | 791,5 (a) | 99,3 (b)\nEHC | (c) | entre 92,5 e 94,6\nEHCP | (d) | entre 95,5 e 96,5\n\n(Adaptado da Resolução ANP nº 907, de 18/11/2022.)\n\nConsiderando que água e etanol formam uma mistura ideal, para preencher corretamente essa tabela, as letras a, b, c e d devem corresponder, respectivamente, a","status":"published","type":"single_choice"}', 'exact equivalent clone; legacy row retained' ) ;
INSERT INTO canonical_question_aliases(alias_question_id, alias_slug, canonical_question_id) VALUES (391, 'vu-2026-ry-q31', 359) ;
